import copy
events=[]
class K:
 def __hash__(self):return 1
 def __deepcopy__(self,memo):
  with open('/input') as f:events.append('key'+f.read(1))
  return self
class V:
 def __deepcopy__(self,memo):
  with open('/input') as f:events.append('value'+f.read(1))
  return self
copy.deepcopy({K():V()});print(events)

import copy
class C:
 def __copy__(self):
  with open('/input') as f:return f.read(1)
print(copy.copy(C()))
